const json = require('./src/examples/quake-pipeline/noodles.json');
const nodeIds = new Set(json.nodes.map(n => n.id));
const errors = [];
for (const e of json.edges) {
  if (!nodeIds.has(e.source)) errors.push('Missing source: ' + e.source);
  if (!nodeIds.has(e.target)) errors.push('Missing target: ' + e.target);
}
if (errors.length) console.log('ERRORS:', errors);
else console.log('All edge references valid. Nodes:', [...nodeIds]);
"

